typedef unsigned int nslSoundId;

extern "C" void nslFatal(const char *, ...);
extern const char nsl_not_initialized[];
extern const char bad_sound_id[];
extern const char bad_sound_slot[];

__asm__(".equ nslFatal__FPCce, 0x00391420");
__asm__(".equ nsl_not_initialized, 0x0051BF80");
__asm__(".equ bad_sound_id, 0x0051BE20");
__asm__(".equ bad_sound_slot, 0x0051BE38");

struct nslSound
{
  int used;
  char pad0[36];
  int pauseCount;
  int dampenCount;
  nslSoundId myId;
  char pad1[36];
};

struct nslSystem
{
  char pad0[0xC044];
  nslSound soundSlots[256];
  char pad1[0x400C];
  int initialized;
  char pad2[44];
  int on;
};

extern nslSystem nsl;
__asm__(".equ nsl, 0x0049B5F0");

inline void _nslCheckSoundIdValidity(nslSoundId checkId)
{
  nslSoundId checkSlot = (checkId & 0x3FF);
  nslSoundId upCheckId = (checkId & 0xFFFFFC00);
  if (checkId == 0)
    nslFatal(bad_sound_id, checkId);
  if (!(nsl.soundSlots[checkSlot].used))
    nslFatal(bad_sound_id, checkId);
  if (!(checkSlot < 256))
    nslFatal(bad_sound_id, checkId);
  if (!(checkId == nsl.soundSlots[checkSlot].myId))
    nslFatal(bad_sound_id, checkId);
  if (!(upCheckId > 0))
    nslFatal(bad_sound_id, checkId);
  if (checkSlot > 256)
    nslFatal(bad_sound_slot, checkId);
}

inline void _nslInitialized()
{
  if (!(nsl.initialized == 1))
    nslFatal(nsl_not_initialized);
}

void nslUnpauseSound( nslSoundId whichSound )
{
  if (!nsl.on) return;
  _nslInitialized();
  _nslCheckSoundIdValidity(whichSound);

  if (nsl.soundSlots[(whichSound&0x000003FF)].pauseCount > 0) 
    nsl.soundSlots[(whichSound&0x000003FF)].pauseCount--;

}
